package ru.fkit.bi.analytics.signal;

import java.util.*;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import ru.fkit.bi.analytics.api.BusinessException;
import ru.fkit.bi.analytics.signal.SignalModels.*;

@Service
class SignalService {
  private final SignalRepository repository;private final TransactionTemplate transactions;
  SignalService(SignalRepository repository,TransactionTemplate transactions){this.repository=repository;this.transactions=transactions;}
  Page<Signal> page(UUID machine,UUID component,String status,String semantic,String kind,Boolean featured,String search,int p,int z){if(!repository.machineExists(machine))throw missing("Machine");validStatus(status);pageBounds(p,z);if(component!=null&&!repository.componentOwned(machine,component))throw new BusinessException(409,"SIGNAL_COMPONENT_OWNER_CONFLICT","Component must belong to the same machine");long n=repository.count(machine,component,status,semantic,kind,featured,search);return new Page<>(repository.page(machine,component,status,semantic,kind,featured,search,p,z),new Metadata(p,z,n,(int)((n+z-1)/z)));}
  Signal create(UUID machine,Create x){if(!repository.machineExists(machine))throw missing("Machine");validate(machine,x.componentId(),x.valueType(),x.signalKind(),x.semanticCode(),x.customSemanticCode(),x.unitCode(),x.expectedIntervalMs(),x.staleAfterMs(),x.validMin(),x.validMax());try{return repository.create(UUID.randomUUID(),machine,x);}catch(DuplicateKeyException e){throw new BusinessException(409,"SIGNAL_CODE_CONFLICT","Signal code already exists in machine");}}
  Signal get(UUID id){return repository.find(id).orElseThrow(()->missing("TelemetrySignal"));}
  Signal update(UUID id,Update x){return transactions.execute(s->{Signal old=get(id);repository.exclusiveSignalLock(id);old=get(id);validate(old.machineId(),x.componentId(),x.valueType(),x.signalKind(),x.semanticCode(),x.customSemanticCode(),x.unitCode(),x.expectedIntervalMs(),x.staleAfterMs(),x.validMin(),x.validMax());if(repository.rawUsed(id)&&(!old.valueType().equals(x.valueType())||!old.signalKind().equals(x.signalKind())||!old.semanticCode().equals(x.semanticCode())||!Objects.equals(old.customSemanticCode(),x.customSemanticCode())||!Objects.equals(old.unitCode(),x.unitCode())))throw new BusinessException(409,"SIGNAL_SEMANTICS_LOCKED","Signal semantic fields cannot change after first raw use");try{repository.update(id,x);}catch(DuplicateKeyException e){throw new BusinessException(409,"SIGNAL_CONFLICT","Signal conflicts with existing configuration");}return get(id);});}
  Signal status(UUID id,StatusUpdate x){return transactions.execute(s->{Signal current=get(id);repository.lockMachine(current.machineId());current=get(id);if("DISABLED".equals(x.status())&&"ACTIVE".equals(current.status())&&repository.referencedByActiveStateMachine(id))throw new BusinessException(409,"SIGNAL_USED_BY_ACTIVE_STATE_CONFIG","Signal is referenced by active machine state configuration");repository.status(id,x.status());return get(id);});}
  private void validate(UUID machine,UUID component,String valueType,String signalKind,String semantic,String custom,String unit,Long interval,Long stale,Double min,Double max){if(component!=null&&!repository.componentOwned(machine,component))throw new BusinessException(409,"SIGNAL_COMPONENT_OWNER_CONFLICT","Component must belong to the same machine");if(!Set.of("DOUBLE","LONG","BOOLEAN","STRING").contains(valueType)||!Set.of("GAUGE","COUNTER","STATE").contains(signalKind))throw new BusinessException(422,"SIGNAL_TYPE_INVALID","valueType or signalKind is not supported");boolean combination=(Set.of("GAUGE","COUNTER").contains(signalKind)&&Set.of("DOUBLE","LONG").contains(valueType))||("STATE".equals(signalKind)&&Set.of("BOOLEAN","LONG","STRING").contains(valueType));if(!combination)throw new BusinessException(422,"SIGNAL_TYPE_KIND_MISMATCH","signalKind is incompatible with valueType");if(!repository.catalogSemantic(semantic))throw new BusinessException(422,"SIGNAL_SEMANTIC_INVALID","semanticCode must identify an active semantic catalog entry");if(("CUSTOM".equals(semantic))!=(custom!=null)||custom!=null&&!custom.matches("^[A-Z][A-Z0-9_]{0,63}$"))throw new BusinessException(422,"SIGNAL_CUSTOM_SEMANTIC_INVALID","customSemanticCode is required only for CUSTOM and must be a stable code");if(!repository.catalogUnit(unit))throw new BusinessException(422,"SIGNAL_UNIT_INVALID","unitCode must identify an active unit");if(interval!=null&&interval<1||stale!=null&&stale<1||interval!=null&&stale!=null&&stale<interval)throw new BusinessException(422,"SIGNAL_FRESHNESS_INVALID","freshness intervals must be positive and staleAfterMs must be at least expectedIntervalMs");if(min!=null&&!Double.isFinite(min)||max!=null&&!Double.isFinite(max)||min!=null&&max!=null&&min>max)throw new BusinessException(422,"SIGNAL_BOUNDS_INVALID","valid bounds must be finite and ordered");if((min!=null||max!=null)&&!Set.of("DOUBLE","LONG").contains(valueType))throw new BusinessException(422,"SIGNAL_BOUNDS_TYPE_INVALID","valid bounds require a numeric signal");}
  private static void validStatus(String v){if(!Set.of("ACTIVE","DISABLED").contains(v))throw new BusinessException(400,"INVALID_STATUS_FILTER","status must be ACTIVE or DISABLED");}
  private static void pageBounds(int p,int z){if(p<0||z<1||z>200)throw new BusinessException(400,"INVALID_PAGINATION","page must be non-negative and size must be 1..200");}
  private static BusinessException missing(String value){return new BusinessException(404,"NOT_FOUND",value+" not found");}
}
